using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes order of gift collections. If the collections are owned by a channel chat, then requires can_post_messages administrator right in the channel chat
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ReorderGiftCollectionsAsync(MessageSender ownerId = default, int[] collectionIds = default)
    {

           using var activity =  StartCallActivity("ReorderGiftCollectionsAsync", typeof(ReorderGiftCollections).FullName ?? "ReorderGiftCollectionsAsync");

           try
           {
             return client.ReorderGiftCollectionsAsync(ownerId, collectionIds);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
